fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Iterate the characters in reverse so we can easily get the last and the
    // one-before-last character.
    let mut rev_chars = txt.chars().rev();

    // Grab the last character, if any.
    let last_char = match rev_chars.next() {
        Some(c) => c,
        None => return false, // empty string
    };

    // The last character must be an ASCII letter.
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Now check the character immediately before the last, if it exists.
    // If there is no such character, that means the string was exactly one
    // character long, which is acceptable. Otherwise, it must be a space.
    match rev_chars.next() {
        None => true,
        Some(prev) => prev == ' ',
    }
}

